SELECT COUNT(*) AS driver_count
FROM users
WHERE user_type = 'driver';

SELECT COUNT(*) AS cancelled_rides
FROM rides
WHERE status = 'cancelled';

SELECT DISTINCT city
FROM users
ORDER BY city;

SELECT AVG(fare) AS average_fare_completed_rides
FROM rides
WHERE status = 'completed';

SELECT status, COUNT(*) AS ride_count
FROM rides
GROUP BY status;

SELECT
  ROUND(
    100.0 * COUNT(*) FILTER (WHERE payment_status = 'failed') / COUNT(*),
    2
  ) AS failed_payment_percentage
FROM payments;

SELECT AVG(distance_km) AS mean_distance_km
FROM rides
WHERE status = 'completed';

SELECT COUNT(*) AS active_driver_count
FROM users
WHERE user_type = 'driver' AND is_active = TRUE;

SELECT SUM(amount) AS total_completed_payment_amount
FROM payments
WHERE payment_status = 'completed';

SELECT COUNT(*) AS ride_count_with_surge
FROM rides
WHERE surge_multiplier > 1;

SELECT make, COUNT(*) AS vehicle_count
FROM vehicles
GROUP BY make;

SELECT COUNT(*) AS ride_requests_2026
FROM rides
WHERE EXTRACT(YEAR FROM requested_at) = 2026;

SELECT AVG(EXTRACT(EPOCH FROM (dropoff_time - pickup_time)) / 60) AS mean_duration_minutes
FROM rides
WHERE status = 'completed';

SELECT driver_id, COUNT(*) AS num_ratings
FROM ratings
GROUP BY driver_id
HAVING COUNT(*) = (
    SELECT MAX(cnt) FROM (
        SELECT COUNT(*) AS cnt
        FROM ratings
        GROUP BY driver_id
    ) t
);

SELECT COUNT(*) AS drivers_without_vehicle
FROM users u
WHERE u.user_type = 'driver'
  AND NOT EXISTS (
    SELECT 1 FROM vehicles v WHERE v.driver_id = u.user_id
  );

SELECT COUNT(DISTINCT user_id) AS user_count
FROM payments
WHERE payment_status = 'failed'
  AND user_id IN (
    SELECE DISTINCT user_id FROM payments WHERE payment_status = 'refunded'
  );
